import{bQ as t,aL as o,u as s,G as a}from"./chunks/framework.C1gZXFVa.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/faq.md","filePath":"en/guide/faq.md"}'),i={name:"en/guide/faq.md"};function n(l,e,r,h,d,c){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><blockquote><p>Find your error message first - this page is organised by symptom. If nothing matches, see &quot;Still stuck?&quot; at the end.</p></blockquote><h2 id="ansible-says-command-not-found-after-installing" tabindex="-1"><code>ansible</code> says &quot;command not found&quot; after installing? <a class="header-anchor" href="#ansible-says-command-not-found-after-installing" aria-label="Permalink to &quot;\`ansible\` says &quot;command not found&quot; after installing?&quot;">​</a></h2><blockquote><p>For regular-user installs, commands are linked into <code>~/.local/bin</code>, which may not be on your PATH yet. Either fix works:</p></blockquote><ul><li>Run <code>export PATH=&quot;$HOME/.local/bin:$PATH&quot;</code> and try again</li><li>Or simply open a new terminal</li></ul><h2 id="the-script-says-python3-is-missing-or-python-3-11-is-required" tabindex="-1">The script says python3 is missing, or Python &gt;= 3.11 is required? <a class="header-anchor" href="#the-script-says-python3-is-missing-or-python-3-11-is-required" aria-label="Permalink to &quot;The script says python3 is missing, or Python &gt;= 3.11 is required?&quot;">​</a></h2><blockquote><p>Install Python for your OS (this does not disturb anything else):</p></blockquote><ul><li>EL 9: <code>sudo dnf install -y python3.11 python3.11-venv</code> (or <code>python3.11-devel</code> if there is no venv subpackage)</li><li>Ubuntu 22.04 / Debian 12: <code>sudo apt install -y python3.11 python3.11-venv</code></li><li>Ubuntu 24.04 ships Python 3.12, so this error should not appear there.</li></ul><h2 id="the-script-says-wheelhouse-not-found" tabindex="-1">The script says &quot;wheelhouse not found&quot;? <a class="header-anchor" href="#the-script-says-wheelhouse-not-found" aria-label="Permalink to &quot;The script says &quot;wheelhouse not found&quot;?&quot;">​</a></h2><blockquote><p>⚠️ Almost always this means only <code>install.sh</code> was copied, or the script was run outside the extracted folder.</p></blockquote><ul><li>Do this instead: extract the full <code>.tar.gz</code>, change into the <code>ansible-offline-install-2.0.0-bundle</code> folder, then run it. The &quot;wheelhouse&quot; is the folder inside the bundle holding all install files; without it, offline installation is impossible.</li></ul><h2 id="does-centos-7-work" tabindex="-1">Does CentOS 7 work? <a class="header-anchor" href="#does-centos-7-work" aria-label="Permalink to &quot;Does CentOS 7 work?&quot;">​</a></h2><blockquote><p>❌ No. CentOS 7 reached end of life in 2024 and its Python is too old for current Ansible.</p></blockquote><ul><li>Please use an EL 9 family system (e.g. Rocky Linux 9). The very first version of this project targeted CentOS 7; it has since been fully rewritten and CentOS 7 is no longer supported.</li></ul><h2 id="will-this-break-my-system-s-python" tabindex="-1">Will this break my system&#39;s Python? <a class="header-anchor" href="#will-this-break-my-system-s-python" aria-label="Permalink to &quot;Will this break my system&#39;s Python?&quot;">​</a></h2><blockquote><p>✅ No. Everything is installed into a dedicated folder; only the <code>ansible</code> commands are linked out.</p></blockquote><ul><li>Locations: <code>/opt/ansible-offline</code> for root installs, <code>~/ansible-offline</code> for regular users. The system Python and other programs are untouched.</li></ul><h2 id="i-don-t-want-the-bundled-collections" tabindex="-1">I don&#39;t want the bundled collections. <a class="header-anchor" href="#i-don-t-want-the-bundled-collections" aria-label="Permalink to &quot;I don&#39;t want the bundled collections.&quot;">​</a></h2><ul><li>Run <code>INSTALL_COLLECTIONS=0 bash install.sh</code> to skip them. A collection is an Ansible plugin package; two popular ones are included by default, see <a href="/en/guide/build">Build Your Own Bundle</a>.</li></ul><h2 id="can-the-scripts-print-in-english-chinese" tabindex="-1">Can the scripts print in English / Chinese? <a class="header-anchor" href="#can-the-scripts-print-in-english-chinese" aria-label="Permalink to &quot;Can the scripts print in English / Chinese?&quot;">​</a></h2><blockquote><p>Yes, two ways:</p></blockquote><ul><li>Command-line flag: <code>bash install.sh --lang en</code></li><li>Environment variable: <code>ANSIBLE_OFFLINE_LANG=en</code></li></ul><blockquote><p>Both scripts speak Chinese by default and support both options.</p></blockquote><h2 id="how-do-i-uninstall" tabindex="-1">How do I uninstall? <a class="header-anchor" href="#how-do-i-uninstall" aria-label="Permalink to &quot;How do I uninstall?&quot;">​</a></h2><ul><li>Delete the install folder and the command links - nothing is left behind:</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># If installed as root:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/ansible-offline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/ansible</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># If installed as a regular user:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/ansible-offline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin/ansible</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span></code></pre></div><h2 id="the-build-machine-cannot-reach-pypi-or-galaxy-no-overseas-network" tabindex="-1">The build machine cannot reach PyPI or Galaxy (no overseas network)? <a class="header-anchor" href="#the-build-machine-cannot-reach-pypi-or-galaxy-no-overseas-network" aria-label="Permalink to &quot;The build machine cannot reach PyPI or Galaxy (no overseas network)?&quot;">​</a></h2><blockquote><p>This is exactly why this project keeps mirrors on China-based platforms:</p></blockquote><ul><li><strong>You just need Ansible installed</strong>: skip building and <a href="/en/guide/download">download a ready-made bundle</a> from the Releases on GitHub or Gitee (Gitee is the China mirror); the bundles already include the collections.</li><li><strong>You do need to build</strong> (e.g. for a different Ansible version): point pip at a domestic mirror by prefixing the build command: <code>PIP_INDEX_URL=https://pypi.tuna.tsinghua.edu.cn/simple bash scripts/make-offline-bundle.sh</code> (Tsinghua mirror shown; Aliyun and others work too).</li></ul><blockquote><p>⚠️ Note: the collections are downloaded from Galaxy overseas and have no stable domestic mirror - if that step cannot connect, use a ready-made bundle instead.</p></blockquote><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><blockquote><p>Open an <a href="https://github.com/ghl1024/ansible-offline-install/issues" target="_blank" rel="noreferrer">Issue</a> in the primary repository. Including these three things saves a lot of back-and-forth:</p></blockquote><ul><li class="todo"><input class="todo-checkbox" type="checkbox" disabled>Your OS version (the output of <code>cat /etc/os-release</code>)</li><li class="todo"><input class="todo-checkbox" type="checkbox" disabled>The exact bundle file name you used</li><li class="todo"><input class="todo-checkbox" type="checkbox" disabled>A screenshot or the full text of the error</li></ul>`,33)])])}const b=t(i,[["render",n]]);export{p as __pageData,b as default};
